import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Category } from './categories.service';

export interface Subscription {
  id: string;
  category: Category;
}

@Injectable({ providedIn: 'root' })
export class SubscriptionsService {
  private readonly http = inject(HttpClient);
  private readonly base = '/api/me/subscriptions';

  list(): Observable<Subscription[]> {
    return this.http.get<Subscription[]>(this.base);
  }

  subscribe(categoryId: string): Observable<Subscription> {
    return this.http.post<Subscription>(this.base, { categoryId });
  }

  unsubscribe(categoryId: string): Observable<void> {
    return this.http.delete<void>(`${this.base}/${categoryId}`);
  }
}

