require('dotenv').config();
const { PrismaPg } = require('@prisma/adapter-pg');
const { PrismaClient } = require('@prisma/client');
const adapter = new PrismaPg({ connectionString: process.env.DATABASE_URL });
const prisma = new PrismaClient({ adapter });

async function main() {
  const testSource = await prisma.source.findFirst({ where: { name: 'FEMA (test duplicate)' } });
  if (testSource) {
    const newsIds = (await prisma.news.findMany({ where: { sourceId: testSource.id }, select: { id: true } })).map(n => n.id);
    const delDeliveries = await prisma.delivery.deleteMany({ where: { newsId: { in: newsIds } } });
    const delNews = await prisma.news.deleteMany({ where: { sourceId: testSource.id } });
    await prisma.source.delete({ where: { id: testSource.id } });
    console.log('deleted deliveries:', delDeliveries.count, 'news:', delNews.count, 'and test source');
  }

  await prisma.category.update({ where: { slug: 'disasters' }, data: { slackWebhookUrl: null } });
  console.log('reset disasters slackWebhookUrl to null');

  const delUser = await prisma.user.deleteMany({ where: { email: 'phase4-test@example.com' } });
  console.log('deleted test user:', delUser.count);
}

main().then(() => prisma.\$disconnect()).catch((e) => { console.error(e); process.exit(1); });
"

